{"path": "/home/agent/workspace/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Why Is the Sky Blue? — 天空为什么是蓝色的？</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --blue:    #3b82f6;
    --blue-d:  #1e3a5f;
    --red:     #ef4444;
    --bg:      #f0f4f8;
    --card:    #ffffff;
    --text:    #1e293b;
    --muted:   #64748b;
    --border:  #e2e8f0;
    --en-bg:   #eff6ff;
    --cn-bg:   #fdf2f2;
  }

  html { scroll-behavior: smooth; }

  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
                 "Helvetica Neue", Arial, "Noto Sans SC", "PingFang SC",
                 "Microsoft YaHei", sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.7;
    min-height: 100vh;
  }

  /* ── Header ─────────────────────────────── */
  header {
    background: linear-gradient(135deg, #1e3a5f 0%, #3b82f6 100%);
    color: #fff;
    text-align: center;
    padding: 2.4rem 1rem 2rem;
    position: relative;
    overflow: hidden;
  }
  header::before {
    content: '';
    position: absolute;
    top: -60%; left: -20%;
    width: 140%; height: 200%;
    background: radial-gradient(ellipse, rgba(255,255,255,.08) 0%, transparent 70%);
    pointer-events: none;
  }
  header h1 {
    font-size: clamp(1.6rem, 4vw, 2.4rem);
    font-weight: 800;
    letter-spacing: .02em;
    margin-bottom: .3rem;
  }
  header .subtitle {
    font-size: clamp(.95rem, 2vw, 1.15rem);
    opacity: .85;
  }

  /* ── Section tabs ───────────────────────── */
  .nav-tabs {
    display: flex;
    justify-content: center;
    gap: .5rem;
    padding: 1.2rem 1rem 0;
    flex-wrap: wrap;
  }
  .nav-tab {
    padding: .55rem 1.4rem;
    border: 2px solid var(--blue);
    border-bottom: none;
    border-radius: 10px 10px 0 0;
    background: var(--card);
    color: var(--blue-d);
    font-weight: 700;
    font-size: .95rem;
    cursor: pointer;
    transition: background .2s, color .2s;
  }
  .nav-tab:hover { background: #dbeafe; }
  .nav-tab.active {
    background: var(--blue);
    color: #fff;
  }

  /* ── Content wrapper ────────────────────── */
  .content {
    max-width: 1360px;
    margin: 0 auto;
    padding: 0 1rem 3rem;
  }

  .panels {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0;
    border-radius: 0 12px 12px 12px;
    overflow: hidden;
    border: 2px solid var(--blue);
    box-shadow: 0 8px 30px rgba(0,0,0,.08);
  }

  .panel {
    background: var(--card);
    padding: 2rem 2.2rem;
    min-height: 300px;
    overflow-y: auto;
  }
  .panel:first-child { background: var(--en-bg); }
  .panel:last-child  { background: var(--cn-bg); }

  .panel-header {
    display: flex;
    align-items: center;
    gap: .6rem;
    margin-bottom: 1.4rem;
    padding-bottom: .8rem;
    border-bottom: 2px solid var(--border);
  }
  .panel-flag { font-size: 1.5rem; }
  .panel-label { font-size: 1.1rem; font-weight: 700; }

  /* ── Markdown-like rendering ────────────── */
  .panel h2 {
    font-size: 1.35rem;
    font-weight: 800;
    margin: 1.8rem 0 .6rem;
    color: var(--blue-d);
  }
  .panel h2:first-child { margin-top: 0; }

  .panel p {
    margin-bottom: 1rem;
    color: var(--text);
  }

  .panel hr {
    border: none;
    height: 2px;
    background: var(--border);
    margin: 1.6rem 0;
    border-radius: 2px;
  }

  .panel b, .panel strong { font-weight: 700; color: var(--blue-d); }

  .panel ol {
    padding-left: 1.6rem;
    margin-bottom: 1rem;
  }
  .panel ol li {
    margin-bottom: .45rem;
    position: relative;
  }
  .panel ol li::marker { color: var(--blue); font-weight: 700; }

  .panel .formula {
    background: #fff;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 1rem 1.2rem;
    margin: 1rem 0 1.2rem;
    text-align: center;
    font-size: 1.05rem;
    overflow-x: auto;
  }
  .panel .formula .caption {
    font-size: .85rem;
    color: var(--muted);
    text-align: left;
    margin-bottom: .5rem;
  }

  /* formula inline helpers */
  sup { font-size: .78em; vertical-align: super; line-height: 0; }
  sub { font-size: .78em; vertical-align: sub; line-height: 0; }
  .mu  { font-family: "Times New Roman", Times, serif; font-style: italic; }
  .sigma, .Omega, .pi, .alpha, .lambda, .epsilon, .theta,
  .omega, .kappa { font-family: "Times New Roman", Times, serif; }

  /* ── Responsive ─────────────────────────── */
  @media (max-width: 820px) {
    .panels { grid-template-columns: 1fr; }
    .panel { padding: 1.4rem 1.2rem; }
  }

  /* ── Scroll bar styling ─────────────────── */
  .panel::-webkit-scrollbar { width: 6px; }
  .panel::-webkit-scrollbar-track { background: transparent; }
  .panel::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 3px; }

  /* ── Footer ─────────────────────────────── */
  footer {
    text-align: center;
    padding: 1.2rem;
    font-size: .82rem;
    color: var(--muted);
    border-top: 1px solid var(--border);
    background: var(--card);
  }
</style>
</head>
<body>

<header>
  <h1>Why Is the Sky Blue? 🌤️</h1>
  <div class="subtitle">天空为什么是蓝色的？</div>
</header>

<nav class="nav-tabs" id="navTabs">
  <button class="nav-tab active" data-section="0">👶 3-Year-Old</button>
  <button class="nav-tab" data-section="1">🎒 High School</button>
  <button class="nav-tab" data-section="2">🎓 Physics PhD</button>
</nav>

<div class="content">
  <div class="panels" id="panels">
    <!-- EN panel -->
    <div class="panel" id="enPanel">
      <div class="panel-header">
        <span class="panel-flag">🇺🇸</span>
        <span class="panel-label">English</span>
      </div>
      <div id="enContent"></div>
    </div>
    <!-- CN panel -->
    <div class="panel" id="cnPanel">
      <div class="panel-header">
        <span class="panel-flag">🇨🇳</span>
        <span class="panel-label">简体中文</span>
      </div>
      <div id="cnContent"></div>
    </div>
  </div>
</div>

<footer>
  A simple bilingual presentation &mdash; no external resources loaded.
</footer>

<script>
/* ── Section data ──────────────────────────────────────────── */
const sections = [
  {
    en: [
      { type: 'p', text: 'The sky is blue because sunlight is made of lots of colors mixed together! When sunlight comes into our air, the blue color likes to bounce around more than the other colors. So when you look up, your eyes see all that happy blue bouncing everywhere! 🎨✨' }
    ],
    cn: [
      { type: 'p', text: '天空是蓝色的，因为阳光里藏着好多好多的颜色！当阳光跑到我们周围的空气中时，蓝色最喜欢蹦蹦跳跳，到处乱跑。所以当你抬头看天，你的眼睛就看到了满满的蓝色在到处蹦跶！🎨✨' }
    ]
  },
  {
    en: [
      { type: 'p', text: 'The sky is blue because of something called <strong>Rayleigh scattering</strong>. Sunlight looks white, but it\'s actually made up of all the colors of the rainbow — each color is a different wavelength of light. Blue light has a shorter wavelength than red light, so when it hits the gas molecules (mostly nitrogen and oxygen) in Earth\'s atmosphere, it gets scattered in all directions much more strongly than longer-wavelength colors like red or yellow. Since blue light is scattered roughly 9–10 times more than red light, when you look up anywhere in the sky (not directly at the Sun), you\'re seeing that scattered blue light filling your field of view. That\'s why the sky appears blue during the day.' },
      { type: 'p', text: '(You might notice red sunsets — that\'s because when the Sun is low on the horizon, blue light has already been scattered away by the time your line of sight reaches it, leaving the longer red and orange wavelengths to dominate.)' }
    ],
    cn: [
      { type: 'p', text: '天空是蓝色的，是因为一个叫<strong>瑞利散射</strong>（Rayleigh scattering）的现象。阳光看起来是白色的，但实际上它包含了彩虹里所有的颜色——每种颜色对应不同的光波长。蓝光的波长比红光短，所以当它撞到地球大气层中的气体分子（主要是氮气和氧气）时，它被向各个方向散射的程度远远大于红光或黄光等长波长的颜色。因为蓝光大约被散射了 9 到 10 倍于红光的量，所以当你抬头看天空的任何一个地方（不直视太阳）时，你看到的就是这些散射的蓝光填满了你的视野。这就是为什么白天天空看起来是蓝色的。' },
      { type: 'p', text: '（你可能会注意到红色的日落——这是因为当太阳靠近地平线时，你的视线到达太阳之前，蓝光已经被散射光了，剩下波长较长的红色和橙色光占主导。）' }
    ]
  },
  {
    en: [
      { type: 'p', text: 'The blue color of the daytime sky is a classical demonstration of <strong>Rayleigh scattering</strong>, first rigorously described by Lord Rayleigh in 1871. When an electromagnetic wave (sunlight) encounters particles much smaller than its wavelength — in this case, the N₂ and O₂ molecules of Earth\'s atmosphere with diameters ~0.3 nm compared to visible wavelengths of 400–700 nm — the induced electric dipole moment of each molecule oscillates at the frequency of the incident field, re-radiating as a dipole antenna.' },
      {
        type: 'formula',
        caption: 'Differential scattering cross-section per molecule:',
        latex: 'dσ / dΩ  =  k⁴ |α|² (1 + cos²θ)  /  (16 π² ε₀²)'
      },
      { type: 'p', text: 'where <em>k = 2π / λ</em> is the wavenumber, <em>α</em> is the molecular polarizability, and <em>θ</em> is the scattering angle. Integrating over solid angle yields the total cross-section:' },
      {
        type: 'formula',
        caption: 'Total cross-section:',
        latex: 'σ  ∝  1 / λ⁴'
      },
      { type: 'p', text: 'This steep <strong>λ⁻⁴</strong> dependence means that shorter wavelengths (blue/violet, ~400–450 nm) are scattered roughly <strong>(700/400)⁴ ≈ 10</strong> times more strongly than longer wavelengths (red, ~700 nm). Although violet light is scattered even more than blue, the sky appears blue because:' },
      {
        type: 'ol',
        items: [
          'The solar spectrum peaks in the green (~500 nm) and has lower spectral radiance in the violet.',
          'Atmospheric absorption (notably by ozone in the Chappuis band and the Hartley band) suppresses the shortest wavelengths.',
          'Human cone sensitivity (the S-cones responsible for short-wavelength perception) is significantly lower in the violet than in the blue.'
        ]
      },
      { type: 'p', text: 'The combination of these factors — the <strong>λ⁻⁴</strong> scattering law, the solar blackbody spectrum (~5778 K), the atmospheric transmission profile, and the spectral response of the human visual system — produces the perceived blue color.' }
    ],
    cn: [
      { type: 'p', text: '白天天空的蓝色是<strong>瑞利散射</strong>的经典例证，该现象最早由瑞利勋爵于 1871 年严格描述。当电磁波（阳光）遇到远小于其波长的粒子时——在此例中，地球大气中的 N₂ 和 O₂ 分子直径约为 0.3 nm，而可见光波长为 400–700 nm——每个分子在入射场频率下产生感应电偶极矩并振荡，像偶极天线一样重新辐射。' },
      {
        type: 'formula',
        caption: '微分散射截面（每个分子）：',
        latex: 'dσ / dΩ  =  k⁴ |α|² (1 + cos²θ)  /  (16 π² ε₀²)'
      },
      { type: 'p', text: '其中 <em>k = 2π / λ</em> 为波数，<em>α</em> 为分子极化率，<em>θ</em> 为散射角。对立体角积分可得总截面：' },
      {
        type: 'formula',
        caption: '总截面：',
        latex: 'σ  ∝  1 / λ⁴'
      },
      { type: 'p', text: '这种强烈的 <strong>λ⁻⁴</strong> 依赖关系意味着较短的波长（蓝/紫光，~400–450 nm）比长波长（红光，~700 nm）被散射得大约 <strong>(700/400)⁴ ≈ 10</strong> 倍。尽管紫光的散射甚至比蓝光更强，但天空呈现蓝色是因为：' },
      {
        type: 'ol',
        items: [
          '太阳光谱在绿光波段（~500 nm）达到峰值，在紫光波段的谱辐射亮度较低。',
          '大气吸收（尤其是臭氧在恰普伊斯带和赫特利带的吸收）抑制了最短波长的光。',
          '人眼视锥细胞的灵敏度（负责短波长感知的 S-视锥细胞）在紫光波段明显低于蓝光波段。'
        ]
      },
      { type: 'p', text: '以上因素的综合作用——<strong>λ⁻⁴</strong> 散射定律、太阳黑体光谱（~5778 K）、大气透射特性以及人视觉系统的频谱响应——共同产生了我们所感知的蓝色。' }
    ]
  }
];

/* ── Render helpers ────────────────────────────────────────── */
function renderBlock(block) {
  switch (block.type) {
    case 'p':
      return '<p>' + block.text + '</p>';
    case 'hr':
      return '<hr>';
    case 'formula':
      return '<div class="formula"><div class="caption">' + block.caption + '</div>' + block.latex + '</div>';
    case 'ol':
      let html = '<ol>';
      block.items.forEach(item => { html += '<li>' + item + '</li>'; });
      return html + '</ol>';
    default:
      return '';
  }
}

function renderSection(enBlocks, cnBlocks) {
  return {
    en: enBlocks.map(renderBlock).join('\n'),
    cn: cnBlocks.map(renderBlock).join('\n')
  };
}

/* ── Tab / section switching ──────────────────────────────── */
const enContent   = document.getElementById('enContent');
const cnContent   = document.getElementById('cnContent');
const tabs        = document.querySelectorAll('.nav-tab');
let currentSection = 0;

function showSection(index) {
  currentSection = index;
  tabs.forEach((t, i) => t.classList.toggle('active', i === index));
  const html = renderSection(sections[index].en, sections[index].cn);
  enContent.innerHTML = html.en;
  cnContent.innerHTML = html.cn;

  // sync scroll position
  enContent.closest('.panel').scrollTop = 0;
  cnContent.closest('.panel').scrollTop = 0;
}

tabs.forEach(tab => {
  tab.addEventListener('click', () => {
    showSection(parseInt(tab.dataset.section));
  });
});

// init
showSection(0);
</script>
</body>
</html>
"}

