      radial-gradient(1px 1px at 10% 20%, rgba(255,255,255,.6), transparent),
      radial-gradient(1px 1px at 30% 65%, rgba(255,255,255,.4), transparent),
      radial-gradient(1.5px 1.5px at 50% 10%, rgba(255,255,255,.7), transparent),
      radial-gradient(1px 1px at 70% 45%, rgba(255,255,255,.5), transparent),
      radial-gradient(1px 1px at 85% 80%, rgba(255,255,255,.4), transparent),
      radial-gradient(1.2px 1.2px at 20% 90%, rgba(255,255,255,.5), transparent),
      radial-gradient(1px 1px at 60% 30%, rgba(255,255,255,.6), transparent),
      radial-gradient(1px 1px at 90% 15%, rgba(255,255,255,.4), transparent),
      radial-gradient(1.3px 1.3px at 45% 75%, rgba(255,255,255,.5), transparent),
      radial-gradient(1px 1px at 5% 50%, rgba(255,255,255,.6), transparent),
      radial-gradient(1px 1px at 78% 55%, rgba(255,255,255,.3), transparent),
      radial-gradient(1.5px 1.5px at 35% 40%, rgba(255,255,255,.5), transparent);
    pointer-events: none;
    z-index: 0;
  }

