    margin-bottom: .4rem;
  }
  header p {
    color: var(--muted);
    font-size: clamp(.95rem, 2vw, 1.15rem);
  }

  /* ── Container ──────────────────────────── */
  .container {
    position: relative;
    z-index: 1;
    max-width: 960px;
    margin: 0 auto;
    padding: 0 1.2rem 4rem;
  }

  /* ── Earth cross-section diagram ────────── */
  .diagram-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin: 2rem 0 3rem;
  }
  .diagram-section h2 {
    font-size: 1.4rem;
