    transform: translateY(-4px);
    box-shadow: 0 12px 36px rgba(0,0,0,.35);
  }

  .layer-card::before {
    content: '';
    position: absolute;
    top: 0; right: 0;
    width: 120px; height: 120px;
    border-radius: 0 16px 0 100%;
    opacity: .08;
    pointer-events: none;
  }

  .layer-card .badge {
    display: inline-block;
    font-size: .75rem;
    font-weight: 700;
