    letter-spacing: .03em;
  }

  .layer-card h3 {
    font-size: 1.4rem;
    font-weight: 800;
    margin-bottom: .3rem;
  }
  .layer-card .en-name {
    font-size: .9rem;
    color: var(--muted);
    margin-bottom: .8rem;
    font-style: italic;
  }
  .layer-card p {
    color: var(--text);
    font-size: .97rem;
    line-height: 1.9;
  }
  .layer-card .stat-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: .6rem;
    margin-top: 1rem;
  }
  .layer-card .stat {
    background: rgba(255,255,255,.04);
    border-radius: 10px;
    padding: .7rem 1rem;
    text-align: center;
  }
  .layer-card .stat .val {
    font-size: 1.3rem;
    font-weight: 800;
    display: block;
  }
  .layer-card .stat .lbl {
    font-size: .78rem;
    color: var(--muted);
  }

  /* Card color variants */
  .layer-card.crust  { border-color: var(--crust); }
  .layer-card.crust  { --card-accent: var(--crust); }
  .layer-card.crust::before { background: var(--crust); }
  .layer-card.crust .badge { background: rgba(139,115,85,.2); color: #c4a87c; }
  .layer-card.crust .stat .val { color: var(--crust); }

  .layer-card.mantle { border-color: var(--mantle); }
  .layer-card.mantle::before { background: var(--mantle); }
  .layer-card.mantle .badge { background: rgba(205,92,60,.2); color: #e08a6b; }
  .layer-card.mantle .stat .val { color: var(--mantle); }

  .layer-card.outer  { border-color: var(--outer); }
  .layer-card.outer::before { background: var(--outer); }
  .layer-card.outer .badge { background: rgba(255,99,71,.2); color: #ff9a8a; }
  .layer-card.outer .stat .val { color: var(--outer); }

  .layer-card.inner  { border-color: var(--inner); }
  .layer-card.inner::before { background: var(--inner); }
  .layer-card.inner .badge { background: rgba(255,215,0,.15); color: #ffe66d; }
