fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0


    if (seconds >= 1.0) {
        return if (seconds == seconds.toLong().toDouble()) {
            "${seconds.toLong()}s"
        } else {
            "${"%.1f".format(seconds)}s"
        }
    }


    val denom = (1.0 / seconds).roundToInt()
    if (denom <= 0) return "0s"

    val reconstructed = 1.0 / denom

    if (kotlin.math.abs(seconds - reconstructed) / seconds <= 0.05) {
        return "1/$denom s"
    }


    return if (seconds >= 0.1) {
        "${"%.2f".format(seconds)}s"
    } else {
        "${"%.3f".format(seconds)}s"
    }
}

